#!/usr/bin/env python3
"""
Turns a raw fbcons font into a C source and a header. The name of the font
gives its size: <anything>_<width>x<height>.bin, like IBM_VGA_8x16.bin. The
font is a bitmap of one glyph after another, one row after another, with the
most significant bit on the left. A row takes whole bytes. The number of
glyphs follows from the size of the file.
"""

import argparse
import os
import re
import sys

# A cell of the console holds one byte
MAX_GLYPHS = 256

BYTES_PER_LINE = 16

HEADER = """\
#pragma once

// Generated by scripts/fbcons/bin_to_ch.py from {name}, do not edit

#define FBCONS_FONT_WIDTH       {width}
#define FBCONS_FONT_HEIGHT      {height}
#define FBCONS_FONT_ROW_BYTES   {row_bytes}
#define FBCONS_FONT_GLYPH_BYTES {glyph_bytes}
#define FBCONS_FONT_GLYPHS      {glyphs}

extern const unsigned char fbcons_font[FBCONS_FONT_GLYPHS * FBCONS_FONT_GLYPH_BYTES];
"""

SOURCE = """\
// Generated by scripts/fbcons/bin_to_ch.py from {name}, do not edit

#include "{header}"

const unsigned char fbcons_font[FBCONS_FONT_GLYPHS * FBCONS_FONT_GLYPH_BYTES] = {{
{body}
}};
"""


def font_size(path):
    stem = os.path.splitext(os.path.basename(path))[0]
    match = re.fullmatch(r".+_([1-9][0-9]*)x([1-9][0-9]*)", stem)

    if match is None:
        sys.exit(f"{path}: the name of a font must end in _<width>x<height>.bin, like IBM_VGA_8x16.bin")

    return int(match.group(1)), int(match.group(2))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("font", help="Raw font")
    parser.add_argument("source", help="C source to write")
    parser.add_argument("header", help="Header to write")
    args = parser.parse_args()

    width, height = font_size(args.font)
    row_bytes = (width + 7) // 8
    glyph_bytes = row_bytes * height

    with open(args.font, "rb") as file:
        data = file.read()

    if not data or len(data) % glyph_bytes:
        sys.exit(f"{args.font}: {len(data)} bytes is not a whole number of {width}x{height} glyphs of {glyph_bytes} bytes")

    glyphs = len(data) // glyph_bytes

    if glyphs > MAX_GLYPHS:
        sys.exit(f"{args.font}: {glyphs} glyphs, but a cell of the console holds one byte, so {MAX_GLYPHS} at most")

    name = os.path.basename(args.font)

    lines = []
    for offset in range(0, len(data), BYTES_PER_LINE):
        lines.append("    " + ", ".join(f"0x{byte:02X}" for byte in data[offset : offset + BYTES_PER_LINE]) + ",")

    with open(args.header, "w") as file:
        file.write(HEADER.format(name=name, width=width, height=height, row_bytes=row_bytes, glyph_bytes=glyph_bytes, glyphs=glyphs))

    with open(args.source, "w") as file:
        file.write(SOURCE.format(name=name, header=os.path.basename(args.header), body="\n".join(lines)))


if __name__ == "__main__":
    main()
